const gcPerm=n=>shuffle(Array.from({length:n},(_,i)=>i));
const gcDistinct=(n,lo,hi)=>{const s=new Set();while(s.size<n)s.add(rnd(lo,hi));return [...s]};
const gcFrac=(a,b)=>{const g=(x,y)=>y?g(y,x%y):x;const d=g(a,b);return b/d===1?String(a/d):`${a/d}/${b/d}`};

