  if(w===1)return gbN(base+`Find the current in the ${b} Ω resistor (in A).`,I*a/(a+b),"A",`I<sub>${b}</sub> = I × ${a}/(${a}+${b}) = ${pfD(I*a/(a+b),3)} A.`,[I*b/(a+b),I/2,I]);
